<header class="admin-page-head"><div><p class="eyebrow">Catalogue</p><h1><?= e($config['label']) ?></h1></div><a class="button button-small" href="/admin/<?= e($resource) ?>/create">New record</a></header><section class="admin-panel"><div class="admin-table-wrap"><table><thead><tr><?php foreach(array_unique(array_merge(['id'],$config['list'])) as $column): ?><th><?= e(ucwords(str_replace('_',' ',$column))) ?></th><?php endforeach; ?><th>Actions</th></tr></thead><tbody><?php foreach($pagination['records'] as $record): ?><tr><?php foreach(array_unique(array_merge(['id'],$config['list'])) as $column): ?><td><?= e(is_array($record[$column]??null)?json_encode($record[$column]):($record[$column]??'—')) ?></td><?php endforeach; ?><td class="table-actions"><a href="/admin/<?= e($resource) ?>/<?= (int)$record['id'] ?>/edit">Edit</a><form action="/admin/<?= e($resource) ?>/<?= (int)$record['id'] ?>/delete" method="post" data-confirm="Remove this record?"><?= csrf_field() ?><button type="submit">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$pagination['records']): ?><div class="empty-state compact"><p>No records yet.</p></div><?php endif; ?></section>

